-- Das Friedrich: printed menu prices and editable internal proposals.
create table if not exists public.menu_prices (
 id uuid primary key default gen_random_uuid(),
 business_id uuid not null references public.businesses(id) on delete cascade,
 menu_key text not null,
 category text not null,
 article_name text not null,
 serving text not null,
 printed_gross_price numeric(10,2) not null check (printed_gross_price >= 0),
 proposed_gross_price numeric(10,2) check (proposed_gross_price >= 0),
 source_note text,
 updated_at timestamptz not null default now(),
 unique (business_id, menu_key)
);
create index if not exists menu_prices_business_category_idx on public.menu_prices (business_id, category);
alter table public.menu_prices enable row level security;
create policy menu_prices_owner_select on public.menu_prices for select to authenticated using (exists (select 1 from public.business_members bm where bm.business_id=menu_prices.business_id and bm.user_id=(select auth.uid()) and bm.role='owner'));
create policy menu_prices_owner_insert on public.menu_prices for insert to authenticated with check (exists (select 1 from public.business_members bm where bm.business_id=menu_prices.business_id and bm.user_id=(select auth.uid()) and bm.role='owner'));
create policy menu_prices_owner_update on public.menu_prices for update to authenticated using (exists (select 1 from public.business_members bm where bm.business_id=menu_prices.business_id and bm.user_id=(select auth.uid()) and bm.role='owner')) with check (exists (select 1 from public.business_members bm where bm.business_id=menu_prices.business_id and bm.user_id=(select auth.uid()) and bm.role='owner'));
grant select, insert, update on public.menu_prices to authenticated;

